use crate::ast::*;

pub fn emit_json(graph: &IntentGraph) -> String {
    serde_json::to_string_pretty(graph)
        .unwrap_or_else(|e| format!("{{\"error\": \"{}\"}}", e))
}

pub fn emit_summary(graph: &IntentGraph) -> String {
    let mut out = String::new();

    for intent in &graph.intents {
        out.push_str(&format!("intent {} {{\n", intent.name));

        if let Some(ctx) = &intent.context {
            out.push_str("  context {\n");
            if let Some(lc) = &ctx.lifecycle {
                match lc {
                    Lifecycle::Ephemeral(d) => {
                        out.push_str(&format!("    lifecycle: ephemeral({})\n", d))
                    }
                    Lifecycle::Persistent => out.push_str("    lifecycle: persistent\n"),
                }
            }
            if let Some(storage) = &ctx.storage {
                out.push_str(&format!("    storage: {}\n", storage));
            }
            out.push_str("  }\n");
        }

        for schema in &intent.schemas {
            out.push_str(&format!(
                "  schema {} ({} fields)\n",
                schema.name,
                schema.fields.len()
            ));
            for field in &schema.fields {
                let annots: Vec<String> = field
                    .annotations
                    .iter()
                    .map(|a| match a {
                        Annotation::Primary => "@primary".to_string(),
                        Annotation::Required => "@required".to_string(),
                        Annotation::Default(v) => format!("@default({})", v),
                        Annotation::Check(e) => format!("@check({})", e),
                        Annotation::Custom { name, arg } => match arg {
                            Some(a) => format!("@{}({})", name, a),
                            None => format!("@{}", name),
                        },
                    })
                    .collect();
                out.push_str(&format!(
                    "    {}: {} {}\n",
                    field.name,
                    field.field_type,
                    annots.join(" ")
                ));
            }
        }

        for action in &intent.actions {
            let params: Vec<String> = action
                .params
                .iter()
                .map(|p| format!("{}: {}", p.name, p.param_type))
                .collect();
            out.push_str(&format!(
                "  action {}({}) [{} stmts]\n",
                action.name,
                params.join(", "),
                action.body.len()
            ));
        }

        for view in &intent.views {
            out.push_str(&format!(
                "  view {} [source: {}, interact: {}]\n",
                view.name,
                view.source,
                view.interactions.join(", ")
            ));
        }

        out.push_str("}\n");
    }

    for func in &graph.functions {
        out.push_str(&format!("fn {}({} params)\n", func.name, func.params.len()));
    }
    for s in &graph.structs {
        out.push_str(&format!("struct {} ({} fields)\n", s.name, s.fields.len()));
    }

    out
}

use serde::{Deserialize, Serialize};

// ============================================================
// 타입 시스템
// ============================================================

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum FlType {
    I64,
    F64,
    String,
    Bool,
    Uuid,
    Custom(String),
}

impl std::fmt::Display for FlType {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            FlType::I64 => write!(f, "i64"),
            FlType::F64 => write!(f, "f64"),
            FlType::String => write!(f, "string"),
            FlType::Bool => write!(f, "bool"),
            FlType::Uuid => write!(f, "uuid"),
            FlType::Custom(s) => write!(f, "{}", s),
        }
    }
}

// ============================================================
// 어노테이션
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Annotation {
    Primary,
    Required,
    Default(String),  // 기본값 (raw 문자열)
    Check(String),    // 제약 표현식 (raw 문자열)
    Custom { name: String, arg: Option<String> },
}

// ============================================================
// 스키마
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SchemaField {
    pub name: String,
    pub field_type: FlType,
    pub annotations: Vec<Annotation>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Schema {
    pub name: String,
    pub fields: Vec<SchemaField>,
}

// ============================================================
// 뷰
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ViewType {
    Grid,
    List,
    Form,
    Custom(String),
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct View {
    pub name: String,
    pub view_type: ViewType,
    pub source: String,
    pub interactions: Vec<String>,
}

// ============================================================
// 컨텍스트
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Lifecycle {
    Ephemeral(String),  // "2h", "30m" 등
    Persistent,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ContextBlock {
    pub lifecycle: Option<Lifecycle>,
    pub storage: Option<String>,
}

// ============================================================
// 표현식 (Expression)
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Expr {
    Int(i64),
    Float(f64),
    Str(String),
    Ident(String),
    BinOp {
        op: String,
        left: Box<Expr>,
        right: Box<Expr>,
    },
    Field {
        object: Box<Expr>,
        field: String,
    },
    Call {
        name: String,
        args: Vec<Expr>,
    },
}

// ============================================================
// 문장 (Statement)
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Assignment {
    pub field: String,
    pub value: Expr,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Stmt {
    Update {
        table: String,
        assignments: Vec<Assignment>,
        condition: Option<Expr>,
    },
    Return(Expr),
    Let {
        name: String,
        value: Expr,
    },
    Assign {
        name: String,
        value: Expr,
    },
    If {
        condition: Expr,
        then_body: Vec<Stmt>,
        else_body: Option<Vec<Stmt>>,
    },
}

// ============================================================
// 액션
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ActionParam {
    pub name: String,
    pub param_type: FlType,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Action {
    pub name: String,
    pub params: Vec<ActionParam>,
    pub body: Vec<Stmt>,
}

// ============================================================
// Intent 노드 (핵심)
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct IntentNode {
    pub name: String,
    pub context: Option<ContextBlock>,
    pub schemas: Vec<Schema>,
    pub actions: Vec<Action>,
    pub views: Vec<View>,
}

// ============================================================
// FreeLang 기본 구조 (fn, struct)
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FnParam {
    pub name: String,
    pub param_type: FlType,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FnDef {
    pub name: String,
    pub params: Vec<FnParam>,
    pub return_type: Option<FlType>,
    pub body: Vec<Stmt>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct StructField {
    pub name: String,
    pub field_type: FlType,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct StructDef {
    pub name: String,
    pub fields: Vec<StructField>,
}

// ============================================================
// 최상위: Intent Graph
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct IntentGraph {
    pub intents: Vec<IntentNode>,
    pub functions: Vec<FnDef>,
    pub structs: Vec<StructDef>,
}

impl IntentGraph {
    pub fn new() -> Self {
        IntentGraph {
            intents: Vec::new(),
            functions: Vec::new(),
            structs: Vec::new(),
        }
    }
}

impl Default for IntentGraph {
    fn default() -> Self {
        Self::new()
    }
}

