// ============================================================
// World Engine CLI - 서브커맨드 파서
// ============================================================

#[derive(Debug, PartialEq)]
pub enum CliCommand {
    /// world new <name>          — 새 .fl 프로젝트 스캐폴딩
    New { name: String },

    /// world run <file.fl> [--port N] [--hot]  — 서버 실행
    Run {
        path: String,
        port: u16,
        hot_reload: bool,
    },

    /// world build <file.fl> [--target ts|go|sql|openapi] [--out dir]
    Build {
        path: String,
        targets: Vec<String>,
        out_dir: String,
    },

    /// world emit <file.fl> <target>   — stdout 출력
    Emit { path: String, target: String },

    /// world validate <file.fl>
    Validate { path: String },

    /// world inspect <file.fl> [--deficiencies|--lifecycle|--routes]
    Inspect { path: String, aspect: InspectAspect },

    /// world help [subcommand]
    Help { topic: Option<String> },

    /// world version
    Version,
}

#[derive(Debug, PartialEq)]
pub enum InspectAspect {
    All,
    Deficiencies,
    Lifecycle,
    Routes,
    Views,
}

impl InspectAspect {
    fn from_flag(s: &str) -> Self {
        match s {
            "--deficiencies" | "-d" => InspectAspect::Deficiencies,
            "--lifecycle"    | "-l" => InspectAspect::Lifecycle,
            "--routes"       | "-r" => InspectAspect::Routes,
            "--views"        | "-v" => InspectAspect::Views,
            _                       => InspectAspect::All,
        }
    }
}

