use std::{env, fs, process};
use world_engine::{
    binder::{router::Router, server::Server},
    cli::{self, CliCommand, InspectAspect},
    deficiency::DeficiencyDetector,
    emitter::{self, EmitTarget},
    lifecycle::LifecycleManager,
    parse, parse_and_validate,
    synthesizer::Synthesizer,
};

fn main() {
    let raw: Vec<String> = env::args().skip(1).collect();

    let cmd = match cli::parse_args(&raw) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("오류: {}", e);
            process::exit(1);
        }
    };

    match cmd {
        CliCommand::Version => {
            println!("World Engine v{}", cli::VERSION);
        }

        CliCommand::Help { topic } => {
            print!("{}", cli::help_text(topic.as_deref()));
        }

        CliCommand::New { name } => cmd_new(&name),

        CliCommand::Run { path, port, hot_reload } => cmd_run(&path, port, hot_reload),

        CliCommand::Build { path, targets, out_dir } => cmd_build(&path, &targets, &out_dir),

        CliCommand::Emit { path, target } => cmd_emit(&path, &target),

        CliCommand::Validate { path } => cmd_validate(&path),

        CliCommand::Inspect { path, aspect } => cmd_inspect(&path, aspect),
    }
}

// ─── new ──────────────────────────────────────────────────

fn cmd_new(name: &str) {
    let dir = std::path::Path::new(name);
    if dir.exists() {
        eprintln!("오류: '{}' 디렉토리가 이미 존재합니다.", name);
        process::exit(1);
    }

    fs::create_dir_all(dir).unwrap_or_else(|e| {
        eprintln!("디렉토리 생성 실패: {}", e);
        process::exit(1);
    });

    let pascal = to_pascal(name);
    let main_fl = format!(
        r#"intent {pascal} {{
    context {{ lifecycle: persistent, storage: KimDB.memory_buffer, }}

    schema Item {{
        id: uuid @primary,
        name: string @required,
        value: i64 @default(0),
    }}

    action create_item(name: string, value: i64) {{
        update Item set value = value where id == id;
        return value;
    }}

    view ItemGrid {{
        type: Grid,
        source: Item,
        interact: [create_item],
    }}
}}
"#,
        pascal = pascal
    );

    let readme = format!(
        "# {name}\n\nWorld Engine 프로젝트\n\n## 실행\n\n```sh\nworld run main.fl\n```\n\n## 코드 생성\n\n```sh\nworld build main.fl\n```\n",
        name = name
    );

    fs::write(dir.join("main.fl"), &main_fl).unwrap_or_else(|e| {
        eprintln!("파일 생성 실패: {}", e);
        process::exit(1);
    });
    fs::write(dir.join("README.md"), &readme).unwrap_or_else(|e| {
        eprintln!("파일 생성 실패: {}", e);
        process::exit(1);
    });

    println!("✓ 프로젝트 생성: {}/", name);
    println!("  {}/main.fl", name);
    println!("  {}/README.md", name);
    println!();
    println!("시작하기:");
    println!("  world run {}/main.fl", name);
}

fn to_pascal(s: &str) -> String {
    s.split(|c: char| c == '-' || c == '_' || c == ' ')
        .map(|w| {
            let mut c = w.chars();
            match c.next() {
                None    => String::new(),
                Some(f) => f.to_uppercase().to_string() + c.as_str(),
            }
        })
        .collect()
}

// ─── run ──────────────────────────────────────────────────

fn cmd_run(path: &str, port: u16, hot_reload: bool) {
    let src = read_file(path);

    let graph = parse(&src).unwrap_or_else(|e| {
        eprintln!("파싱 오류: {}", e);
        process::exit(1);
    });

    let result = Synthesizer::synthesize(&graph);
    println!("{}", result.summary());

    let router = Router::from_graph(graph.clone());
    println!("라우트:");
    for r in &router.routes {
        println!("  {} {}", r.method, r.path);
    }
    println!();

    let server = if hot_reload {
        Server::new(router, result.db, port)
            .with_hot_reload(path)
    } else {
        Server::new(router, result.db, port)
    };

    server.start().unwrap_or_else(|e| {
        eprintln!("서버 오류: {}", e);
        process::exit(1);
    });
}

// ─── build ────────────────────────────────────────────────

fn cmd_build(path: &str, targets: &[String], out_dir: &str) {
    let src = read_file(path);
    let (graph, errors) = parse_and_validate(&src).unwrap_or_else(|e| {
        eprintln!("파싱 오류: {}", e);
        process::exit(1);
    });

    if !errors.is_empty() {
        eprintln!("검증 경고 ({}):", errors.len());
        for e in &errors {
            eprintln!("  {}", e);
        }
    }

    fs::create_dir_all(out_dir).unwrap_or_else(|e| {
        eprintln!("출력 디렉토리 생성 실패: {}", e);
        process::exit(1);
    });

    let target_map: &[(&str, &str, EmitTarget)] = &[
        ("typescript", "typescript.ts",     EmitTarget::TypeScript),
        ("ts",         "typescript.ts",     EmitTarget::TypeScript),
