use crate::ast::{IntentGraph, IntentNode, Stmt};

// ============================================================
// 결핍 심각도
// ============================================================

#[derive(Debug, Clone, PartialEq)]
pub enum Severity {
    Error,    // 기능 동작 불가
    Warning,  // 동작은 하지만 불완전
    Info,     // 개선 권장
}

impl std::fmt::Display for Severity {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Severity::Error   => write!(f, "error"),
            Severity::Warning => write!(f, "warning"),
            Severity::Info    => write!(f, "info"),
        }
    }
}

// ============================================================
// 결핍 종류
// ============================================================

#[derive(Debug, Clone, PartialEq)]
pub enum DeficiencyKind {
    NoPrimaryKey,        // 스키마에 @primary 없음
    NoReturnInAction,    // action에 return 문 없음
    NoViewInteractions,  // view의 interact가 비어있음
    NoViews,             // intent에 view가 없음
    NoActions,           // intent에 action이 없음
    OrphanSchema,        // 어떤 view에서도 source로 참조 안 됨
    OrphanAction,        // 어떤 view의 interact에도 없는 action
    EmptySchema,         // 필드가 없는 스키마
    NoContext,           // context 블록 없음 (lifecycle 미정의)
}

impl std::fmt::Display for DeficiencyKind {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let s = match self {
            DeficiencyKind::NoPrimaryKey       => "no_primary_key",
            DeficiencyKind::NoReturnInAction   => "no_return_in_action",
            DeficiencyKind::NoViewInteractions => "no_view_interactions",
            DeficiencyKind::NoViews            => "no_views",
            DeficiencyKind::NoActions          => "no_actions",
            DeficiencyKind::OrphanSchema       => "orphan_schema",
            DeficiencyKind::OrphanAction       => "orphan_action",
            DeficiencyKind::EmptySchema        => "empty_schema",
            DeficiencyKind::NoContext          => "no_context",
        };
        write!(f, "{}", s)
    }
}

// ============================================================
// Deficiency - 결핍 항목
// ============================================================

#[derive(Debug, Clone)]
pub struct Deficiency {
    pub kind: DeficiencyKind,
    pub severity: Severity,
    pub intent: String,
    pub target: String,       // 대상: 스키마명, action명, view명 등
    pub message: String,
    pub suggestion: String,
}

impl Deficiency {
    pub fn to_json(&self) -> serde_json::Value {
        serde_json::json!({
            "kind": self.kind.to_string(),
            "severity": self.severity.to_string(),
            "intent": self.intent,
            "target": self.target,
            "message": self.message,
            "suggestion": self.suggestion,
        })
    }
}

// ============================================================
// DeficiencyDetector
// ============================================================

pub struct DeficiencyDetector;

impl DeficiencyDetector {
    pub fn analyze(graph: &IntentGraph) -> Vec<Deficiency> {
        let mut result = Vec::new();

        for intent in &graph.intents {
            Self::check_intent(intent, &mut result);
        }

        result
    }

    fn check_intent(intent: &IntentNode, out: &mut Vec<Deficiency>) {
        // ① context 없음
        if intent.context.is_none() {
            out.push(Deficiency {
                kind: DeficiencyKind::NoContext,
                severity: Severity::Info,
                intent: intent.name.clone(),
                target: intent.name.clone(),
                message: format!("'{}' intent에 context 블록이 없습니다", intent.name),
                suggestion: "context { lifecycle: persistent, storage: KimDB.memory_buffer } 추가를 권장합니다".to_string(),
            });
        }

        // ② view 없음
        if intent.views.is_empty() {
            out.push(Deficiency {
                kind: DeficiencyKind::NoViews,
                severity: Severity::Warning,
                intent: intent.name.clone(),
                target: intent.name.clone(),
                message: format!("'{}' intent에 view가 없습니다", intent.name),
                suggestion: "view 정의를 추가하면 자동 HTML UI와 FreeWire 노드가 생성됩니다".to_string(),
            });
        }

        // ③ action 없음
        if intent.actions.is_empty() {
            out.push(Deficiency {
                kind: DeficiencyKind::NoActions,
                severity: Severity::Warning,
                intent: intent.name.clone(),
                target: intent.name.clone(),
                message: format!("'{}' intent에 action이 없습니다", intent.name),
                suggestion: "action을 추가하면 POST 엔드포인트가 자동 생성됩니다".to_string(),
            });
        }

        // ④ 스키마별 검사
        let view_sources: Vec<&str> = intent.views.iter()
            .map(|v| v.source.as_str())
            .collect();

        for schema in &intent.schemas {
            // 빈 스키마
            if schema.fields.is_empty() {
                out.push(Deficiency {
                    kind: DeficiencyKind::EmptySchema,
                    severity: Severity::Error,
                    intent: intent.name.clone(),
                    target: schema.name.clone(),
                    message: format!("스키마 '{}.{}' 에 필드가 없습니다", intent.name, schema.name),
                    suggestion: format!("schema {} {{ id: uuid @primary, ... }} 형식으로 필드를 추가하세요", schema.name),
                });
                continue;
            }

            // @primary 없음
            let has_primary = schema.fields.iter()
                .any(|f| f.annotations.iter().any(|a| matches!(a, crate::ast::Annotation::Primary)));
            if !has_primary {
                out.push(Deficiency {
                    kind: DeficiencyKind::NoPrimaryKey,
                    severity: Severity::Warning,
                    intent: intent.name.clone(),
                    target: schema.name.clone(),
                    message: format!("스키마 '{}.{}' 에 @primary 필드가 없습니다", intent.name, schema.name),
                    suggestion: format!("id: uuid @primary 필드 추가를 권장합니다 (UUID 자동 생성)", ),
                });
            }

            // 고아 스키마 (view.source에 없음)
            if !view_sources.contains(&schema.name.as_str()) {
                out.push(Deficiency {
                    kind: DeficiencyKind::OrphanSchema,
                    severity: Severity::Info,
                    intent: intent.name.clone(),
                    target: schema.name.clone(),
                    message: format!("스키마 '{}.{}' 가 어떤 view에서도 source로 사용되지 않습니다", intent.name, schema.name),
                    suggestion: format!("view {{ type: Grid, source: {}, interact: [] }} 추가를 고려하세요", schema.name),
                });
            }
        }

        // ⑤ action별 검사
        let view_interacts: Vec<&str> = intent.views.iter()
            .flat_map(|v| v.interactions.iter().map(|s| s.as_str()))
            .collect();

        for action in &intent.actions {
            // return 없음
            let has_return = action.body.iter().any(|s| matches!(s, Stmt::Return(_)));
            if !has_return {
                out.push(Deficiency {
                    kind: DeficiencyKind::NoReturnInAction,
                    severity: Severity::Info,
                    intent: intent.name.clone(),
                    target: action.name.clone(),
                    message: format!("action '{}.{}' 에 return 문이 없습니다", intent.name, action.name),
                    suggestion: "return 문 추가 시 API 응답에 결과값이 포함됩니다".to_string(),
                });
            }

            // 고아 action (어떤 view의 interact에도 없음)
            if !view_interacts.contains(&action.name.as_str()) {
                out.push(Deficiency {
                    kind: DeficiencyKind::OrphanAction,
                    severity: Severity::Info,
                    intent: intent.name.clone(),
                    target: action.name.clone(),
                    message: format!("action '{}.{}' 가 어떤 view의 interact에도 없습니다", intent.name, action.name),
                    suggestion: format!("view의 interact: [{}] 에 추가하면 UI 버튼이 생성됩니다", action.name),
                });
            }
        }

        // ⑥ view별 검사
        for view in &intent.views {
            if view.interactions.is_empty() {
                out.push(Deficiency {
                    kind: DeficiencyKind::NoViewInteractions,
                    severity: Severity::Info,
                    intent: intent.name.clone(),
                    target: view.name.clone(),
                    message: format!("view '{}.{}' 의 interact가 비어있습니다", intent.name, view.name),
                    suggestion: "interact: [action명, ...] 을 추가하면 UI에 버튼이 생성됩니다".to_string(),
                });
            }
        }
    }

    // JSON 보고서 생성
    pub fn report_json(graph: &IntentGraph) -> serde_json::Value {
        let deficiencies = Self::analyze(graph);

        let errors   = deficiencies.iter().filter(|d| d.severity == Severity::Error).count();
        let warnings = deficiencies.iter().filter(|d| d.severity == Severity::Warning).count();
        let infos    = deficiencies.iter().filter(|d| d.severity == Severity::Info).count();

        // intent별 그룹핑
        let mut by_intent: std::collections::HashMap<String, Vec<serde_json::Value>> =
            std::collections::HashMap::new();
        for d in &deficiencies {
            by_intent.entry(d.intent.clone())
                .or_default()
                .push(d.to_json());
        }

        let grouped: Vec<serde_json::Value> = by_intent.into_iter().map(|(intent, items)| {
            serde_json::json!({
                "intent": intent,
                "count": items.len(),
                "items": items,
            })
        }).collect();

        serde_json::json!({
            "total": deficiencies.len(),
            "summary": {
                "errors": errors,
                "warnings": warnings,
                "infos": infos,
            },
            "healthy": deficiencies.is_empty(),
            "by_intent": grouped,
        })
    }
}

use crate::ast::*;

// ============================================================
// 타겟 언어
// ============================================================

#[derive(Debug, Clone, PartialEq)]
pub enum EmitTarget {
    TypeScript,
    Go,
    Sql,       // SQL DDL (CREATE TABLE)
    OpenApi,   // OpenAPI 3.0 YAML
    Json,      // 기존 JSON 덤프
    Summary,   // 기존 텍스트 요약
}

impl EmitTarget {
    pub fn from_str(s: &str) -> Option<Self> {
        match s.trim().to_lowercase().as_str() {
            "typescript" | "ts" => Some(EmitTarget::TypeScript),
            "go" | "golang"     => Some(EmitTarget::Go),
            "sql"               => Some(EmitTarget::Sql),
            "openapi" | "yaml"  => Some(EmitTarget::OpenApi),
            "json"              => Some(EmitTarget::Json),
            "summary" | "text"  => Some(EmitTarget::Summary),
            _                   => None,
        }
    }
}

// ============================================================
// 공개 진입점
// ============================================================

pub fn emit(graph: &IntentGraph, target: EmitTarget) -> String {
    match target {
        EmitTarget::TypeScript => emit_typescript(graph),
        EmitTarget::Go         => emit_go(graph),
        EmitTarget::Sql        => emit_sql(graph),
        EmitTarget::OpenApi    => emit_openapi(graph),
        EmitTarget::Json       => emit_json(graph),
        EmitTarget::Summary    => emit_summary(graph),
    }
}

// ============================================================
// TypeScript 생성
// ============================================================

pub fn emit_typescript(graph: &IntentGraph) -> String {
    let mut out = String::from("// Auto-generated by World Engine\n// DO NOT EDIT\n\n");

    for intent in &graph.intents {
        out.push_str(&format!("// ── {} ─────────────────────────────\n\n", intent.name));

        // 스키마 → interface
        for schema in &intent.schemas {
            out.push_str(&format!("export interface {} {{\n", schema.name));
            for field in &schema.fields {
                let ts_type = fl_to_ts(&field.field_type);
                let optional = !field.annotations.iter().any(|a| matches!(a, Annotation::Required | Annotation::Primary));
                if optional {
                    out.push_str(&format!("  {}?: {};\n", field.name, ts_type));
                } else {
                    out.push_str(&format!("  {}: {};\n", field.name, ts_type));
                }
            }
            out.push_str("}\n\n");
        }

        // action → async 함수 시그니처
        for action in &intent.actions {
            let params: Vec<String> = action.params.iter()
                .map(|p| format!("{}: {}", p.name, fl_to_ts(&p.param_type)))
                .collect();
            let schema_name = intent.schemas.first().map(|s| s.name.as_str()).unwrap_or("unknown");
            out.push_str(&format!(
                "export async function {}({}): Promise<{}[]> {{\n  // TODO: implement\n  throw new Error('not implemented');\n}}\n\n",
                action.name, params.join(", "), schema_name
            ));
        }

        // API client helper
        if !intent.actions.is_empty() || !intent.schemas.is_empty() {
            out.push_str(&format!("export const {}Api = {{\n", camel_lower(&intent.name)));
            for schema in &intent.schemas {
                out.push_str(&format!(
                    "  getAll{}: (): Promise<{}[]> => fetch('/{}/{}').then(r => r.json()),\n",
                    schema.name, schema.name, intent.name, schema.name
                ));
            }
            for action in &intent.actions {
                let params: Vec<String> = action.params.iter()
                    .map(|p| format!("{}: {}", p.name, fl_to_ts(&p.param_type)))
                    .collect();
                out.push_str(&format!(
                    "  {}: ({}) => fetch('/{}/{}', {{ method: 'POST', headers: {{'Content-Type': 'application/json'}}, body: JSON.stringify({{ {} }}) }}).then(r => r.json()),\n",
                    action.name,
                    params.join(", "),
                    intent.name, action.name,
                    action.params.iter().map(|p| p.name.as_str()).collect::<Vec<_>>().join(", ")
                ));
            }
            out.push_str("};\n\n");
        }
    }

    // 독립 struct → interface
    for s in &graph.structs {
        out.push_str(&format!("export interface {} {{\n", s.name));
        for field in &s.fields {
            out.push_str(&format!("  {}: {};\n", field.name, fl_to_ts(&field.field_type)));
        }
        out.push_str("}\n\n");
    }

    out
}

fn fl_to_ts(t: &FlType) -> &'static str {
    match t {
        FlType::I64    => "number",
        FlType::F64    => "number",
        FlType::String => "string",
        FlType::Bool   => "boolean",
        FlType::Uuid   => "string",
        FlType::Custom(_) => "unknown",
    }
}

fn camel_lower(s: &str) -> String {
    let mut c = s.chars();
    match c.next() {
        None => String::new(),
        Some(f) => f.to_lowercase().to_string() + c.as_str(),
    }
}

// ============================================================
// Go 생성
// ============================================================

pub fn emit_go(graph: &IntentGraph) -> String {
    let mut out = String::from("// Auto-generated by World Engine\n// DO NOT EDIT\n\npackage generated\n\nimport \"github.com/google/uuid\"\n\n");

    for intent in &graph.intents {
        out.push_str(&format!("// ── {} ─────────────────────────────\n\n", intent.name));

        // 스키마 → struct
        for schema in &intent.schemas {
            out.push_str(&format!("type {} struct {{\n", schema.name));
            for field in &schema.fields {
                let go_type = fl_to_go(&field.field_type);
                let is_optional = !field.annotations.iter().any(|a| matches!(a, Annotation::Required | Annotation::Primary));
                let tag = format!("`json:\"{}\"`", snake_case(&field.name));
                if is_optional {
                    out.push_str(&format!("\t{} *{} {}\n", pascal_case(&field.name), go_type, tag));
                } else {
                    out.push_str(&format!("\t{} {} {}\n", pascal_case(&field.name), go_type, tag));
                }
            }
            out.push_str("}\n\n");
        }

        // action → 인터페이스 메서드
        if !intent.actions.is_empty() {
            out.push_str(&format!("type {}Service interface {{\n", intent.name));
            for action in &intent.actions {
                let params: Vec<String> = action.params.iter()
                    .map(|p| format!("{} {}", p.name, fl_to_go(&p.param_type)))
                    .collect();
                let return_type = intent.schemas.first()
                    .map(|s| format!("([]{}, error)", s.name))
                    .unwrap_or_else(|| "(interface{}, error)".into());
                out.push_str(&format!("\t{}({}) {}\n", pascal_case(&action.name), params.join(", "), return_type));
            }
            out.push_str("}\n\n");
        }
    }

    // 독립 struct
    for s in &graph.structs {
        out.push_str(&format!("type {} struct {{\n", s.name));
        for field in &s.fields {
            let tag = format!("`json:\"{}\"`", snake_case(&field.name));
            out.push_str(&format!("\t{} {} {}\n", pascal_case(&field.name), fl_to_go(&field.field_type), tag));
        }
        out.push_str("}\n\n");
    }

    // uuid import 제거 (사용 안 하면)
    let uses_uuid = out.contains("uuid.UUID");
    if !uses_uuid {
        out = out.replace("import \"github.com/google/uuid\"\n\n", "");
    }

    out
}

fn fl_to_go(t: &FlType) -> &'static str {
    match t {
        FlType::I64    => "int64",
        FlType::F64    => "float64",
        FlType::String => "string",
        FlType::Bool   => "bool",
        FlType::Uuid   => "uuid.UUID",
        FlType::Custom(_) => "interface{}",
    }
}

fn pascal_case(s: &str) -> String {
    s.split('_')
        .map(|w| {
            let mut c = w.chars();
            match c.next() {
                None => String::new(),
                Some(f) => f.to_uppercase().to_string() + c.as_str(),
            }
        })
        .collect()
}

fn snake_case(s: &str) -> String {
    // camelCase → snake_case
    let mut out = String::new();
    for (i, c) in s.chars().enumerate() {
        if c.is_uppercase() && i > 0 {
            out.push('_');
            out.push(c.to_lowercase().next().unwrap());
        } else {
            out.push(c.to_lowercase().next().unwrap_or(c));
        }
    }
    out
}

// ============================================================
// SQL DDL 생성
// ============================================================

pub fn emit_sql(graph: &IntentGraph) -> String {
    let mut out = String::from("-- Auto-generated by World Engine\n-- DO NOT EDIT\n\n");

    for intent in &graph.intents {
        for schema in &intent.schemas {
            out.push_str(&format!("-- {} > {}\n", intent.name, schema.name));
            out.push_str(&format!("CREATE TABLE IF NOT EXISTS {} (\n", schema.name));

            let cols: Vec<String> = schema.fields.iter().map(|f| {
                let sql_type = fl_to_sql(&f.field_type);
                let mut constraints = Vec::new();

                for ann in &f.annotations {
                    match ann {
                        Annotation::Primary  => constraints.push("PRIMARY KEY"),
                        Annotation::Required => constraints.push("NOT NULL"),
                        Annotation::Default(v) => {
                            // default는 문자열로 추가 (owned이므로 별도 처리)
                            let _ = v; // handled below
                        }
                        _ => {}
                    }
                }

                let defaults: Vec<String> = f.annotations.iter().filter_map(|a| {
                    if let Annotation::Default(v) = a {
                        Some(format!("DEFAULT {}", v))
                    } else {
                        None
                    }
                }).collect();

                let mut parts = format!("  {} {}", f.name, sql_type);
                for c in &constraints {
                    parts.push(' ');
                    parts.push_str(c);
                }
                for d in &defaults {
                    parts.push(' ');
                    parts.push_str(d);
                }
                parts
            }).collect();

            out.push_str(&cols.join(",\n"));
            out.push_str("\n);\n\n");
        }
    }

    // 독립 struct도 테이블로
    for s in &graph.structs {
        out.push_str(&format!("CREATE TABLE IF NOT EXISTS {} (\n", s.name));
        let cols: Vec<String> = s.fields.iter()
            .map(|f| format!("  {} {}", f.name, fl_to_sql(&f.field_type)))
            .collect();
        out.push_str(&cols.join(",\n"));
        out.push_str("\n);\n\n");
    }

    out
}

fn fl_to_sql(t: &FlType) -> &'static str {
    match t {
        FlType::I64    => "INTEGER",
        FlType::F64    => "REAL",
        FlType::String => "TEXT",
        FlType::Bool   => "INTEGER", // SQLite
        FlType::Uuid   => "TEXT",
        FlType::Custom(_) => "TEXT",
    }
}

// ============================================================
// OpenAPI 3.0 YAML 생성
// ============================================================

pub fn emit_openapi(graph: &IntentGraph) -> String {
    let mut out = String::from(
        "openapi: 3.0.0\ninfo:\n  title: World Engine API\n  version: 1.0.0\n  description: Auto-generated by World Engine\n\npaths:\n"
    );

    for intent in &graph.intents {
        // GET /{intent}/{schema}
        for schema in &intent.schemas {
            out.push_str(&format!("  /{}/{}:\n", intent.name, schema.name));
            out.push_str("    get:\n");
            out.push_str(&format!("      summary: List all {}\n", schema.name));
            out.push_str("      responses:\n");
            out.push_str("        '200':\n");
            out.push_str("          description: Success\n");
            out.push_str("          content:\n");
            out.push_str("            application/json:\n");
            out.push_str("              schema:\n");
            out.push_str("                type: object\n");
            out.push_str("                properties:\n");
            out.push_str(&format!("                  table:\n                    type: string\n                    example: {}\n", schema.name));
            out.push_str("                  count:\n                    type: integer\n");
            out.push_str(&format!("                  rows:\n                    type: array\n                    items:\n                      $ref: '#/components/schemas/{}'\n", schema.name));
        }

        // POST /{intent}/{action}
        for action in &intent.actions {
            out.push_str(&format!("  /{}/{}:\n", intent.name, action.name));
            out.push_str("    post:\n");
            out.push_str(&format!("      summary: Execute action {}\n", action.name));
            if !action.params.is_empty() {
                out.push_str("      requestBody:\n");
                out.push_str("        required: true\n");
                out.push_str("        content:\n");
                out.push_str("          application/json:\n");
                out.push_str("            schema:\n");
                out.push_str("              type: object\n");
                out.push_str("              properties:\n");
                for p in &action.params {
                    let oa_type = fl_to_openapi_type(&p.param_type);
                    out.push_str(&format!("                {}:\n                  type: {}\n", p.name, oa_type));
                }
            }
            out.push_str("      responses:\n");
            out.push_str("        '200':\n");
            out.push_str("          description: Success\n");
            out.push_str("          content:\n");
            out.push_str("            application/json:\n");
            out.push_str("              schema:\n");
            out.push_str("                type: object\n");
            out.push_str("                properties:\n");
            out.push_str("                  ok:\n                    type: boolean\n");
            out.push_str("        '400':\n");
            out.push_str("          description: Bad Request\n");
        }
    }

    // Mutation 엔드포인트
    out.push_str("  /mutate:\n");
    out.push_str("    post:\n");
    out.push_str("      summary: Apply a mutation to the intent graph\n");
    out.push_str("      requestBody:\n");
    out.push_str("        required: true\n");
    out.push_str("        content:\n");
    out.push_str("          application/json:\n");
    out.push_str("            schema:\n");
    out.push_str("              $ref: '#/components/schemas/MutationOp'\n");
    out.push_str("      responses:\n");
    out.push_str("        '200':\n");
    out.push_str("          description: Mutation applied\n");
    out.push_str("        '400':\n");
    out.push_str("          description: Invalid mutation\n");

    out.push_str("  /mutations:\n");
    out.push_str("    get:\n");
    out.push_str("      summary: Get mutation history\n");
    out.push_str("      responses:\n");
    out.push_str("        '200':\n");
    out.push_str("          description: Mutation log\n");

    // Components
    out.push_str("\ncomponents:\n  schemas:\n");

    for intent in &graph.intents {
        for schema in &intent.schemas {
            out.push_str(&format!("    {}:\n", schema.name));
            out.push_str("      type: object\n");
            if !schema.fields.is_empty() {
                // required 필드 목록
                let required_fields: Vec<&str> = schema.fields.iter()
                    .filter(|f| f.annotations.iter().any(|a| matches!(a, Annotation::Required | Annotation::Primary)))
                    .map(|f| f.name.as_str())
                    .collect();
                if !required_fields.is_empty() {
                    out.push_str("      required:\n");
                    for r in &required_fields {
                        out.push_str(&format!("        - {}\n", r));
                    }
                }
                out.push_str("      properties:\n");
                for field in &schema.fields {
                    let oa_type = fl_to_openapi_type(&field.field_type);
                    let oa_format = fl_to_openapi_format(&field.field_type);
                    out.push_str(&format!("        {}:\n          type: {}\n", field.name, oa_type));
                    if let Some(fmt) = oa_format {
                        out.push_str(&format!("          format: {}\n", fmt));
                    }
                }
            }
        }
    }

    // MutationOp schema
    out.push_str("    MutationOp:\n      type: object\n      required:\n        - op\n        - intent\n");
    out.push_str("      properties:\n");
    out.push_str("        op:\n          type: string\n          enum: [add_field, remove_field, add_view, remove_view, set_lifecycle]\n");
    out.push_str("        intent:\n          type: string\n");
    out.push_str("        schema:\n          type: string\n");
    out.push_str("        field_name:\n          type: string\n");
    out.push_str("        field_type:\n          type: string\n");
    out.push_str("        view_name:\n          type: string\n");
    out.push_str("        lifecycle:\n          type: string\n");

    out
}

fn fl_to_openapi_type(t: &FlType) -> &'static str {
    match t {
        FlType::I64    => "integer",
        FlType::F64    => "number",
        FlType::String => "string",
        FlType::Bool   => "boolean",
        FlType::Uuid   => "string",
        FlType::Custom(_) => "string",
    }
}

fn fl_to_openapi_format(t: &FlType) -> Option<&'static str> {
    match t {
        FlType::I64  => Some("int64"),
        FlType::F64  => Some("double"),
        FlType::Uuid => Some("uuid"),
        _            => None,
    }
}

// ============================================================
// JSON (기존 유지)
// ============================================================

pub fn emit_json(graph: &IntentGraph) -> String {
    serde_json::to_string_pretty(graph)
        .unwrap_or_else(|e| format!("{{\"error\": \"{}\"}}", e))
}

// ============================================================
// Summary (기존 유지)
// ============================================================

pub fn emit_summary(graph: &IntentGraph) -> String {
    let mut out = String::new();

    for intent in &graph.intents {
        out.push_str(&format!("intent {} {{\n", intent.name));

        if let Some(ctx) = &intent.context {
            out.push_str("  context {\n");
            if let Some(lc) = &ctx.lifecycle {
                match lc {
                    Lifecycle::Ephemeral(d) => out.push_str(&format!("    lifecycle: ephemeral({})\n", d)),
                    Lifecycle::Persistent   => out.push_str("    lifecycle: persistent\n"),
                }
            }
            if let Some(storage) = &ctx.storage {
                out.push_str(&format!("    storage: {}\n", storage));
            }
            out.push_str("  }\n");
        }

        for schema in &intent.schemas {
            out.push_str(&format!("  schema {} ({} fields)\n", schema.name, schema.fields.len()));
            for field in &schema.fields {
                let annots: Vec<String> = field.annotations.iter().map(|a| match a {
                    Annotation::Primary      => "@primary".to_string(),
                    Annotation::Required     => "@required".to_string(),
                    Annotation::Default(v)   => format!("@default({})", v),
                    Annotation::Check(e)     => format!("@check({})", e),
                    Annotation::Custom { name, arg } => match arg {
                        Some(a) => format!("@{}({})", name, a),
                        None    => format!("@{}", name),
                    },
                }).collect();
                out.push_str(&format!("    {}: {} {}\n", field.name, field.field_type, annots.join(" ")));
            }
        }

        for action in &intent.actions {
            let params: Vec<String> = action.params.iter()
                .map(|p| format!("{}: {}", p.name, p.param_type))
                .collect();
            out.push_str(&format!("  action {}({}) [{} stmts]\n", action.name, params.join(", "), action.body.len()));
        }

        for view in &intent.views {
            out.push_str(&format!("  view {} [source: {}, interact: {}]\n",
                view.name, view.source, view.interactions.join(", ")));
        }

        out.push_str("}\n");
    }

    for func in &graph.functions {
        out.push_str(&format!("fn {}({} params)\n", func.name, func.params.len()));
    }
    for s in &graph.structs {
        out.push_str(&format!("struct {} ({} fields)\n", s.name, s.fields.len()));
    }

    out
}

