   138→    // ─── INSERT ───────────────────────────────────────────────
   139→
   140→    pub fn insert(&mut self, table_name: &str, mut row: Row) -> Result<String, DbError> {
   141→        let table = self.tables.get(table_name)
   142→            .ok_or_else(|| DbError::TableNotFound(table_name.to_string()))?;
   143→
   144→        // Clone what we need to avoid borrow issues
   145→        let columns = table.columns.clone();
   146→        let primary_key = table.primary_key.clone();
   147→        let next_seq = table.next_seq;
   148→
   149→        // 1. 기본값 적용 & UUID 자동 생성
   150→        for col in &columns {
   151→            if row.contains_key(&col.name) {
   152→                continue;
   153→            }
   154→            // @primary + uuid → 자동 UUID
   155→            if matches!(col.col_type, FlType::Uuid)
   156→                && col.annotations.iter().any(|a| matches!(a, Annotation::Primary))
   157→            {
   158→                let uuid = self.gen_uuid();
   159→                let table = self.tables.get_mut(table_name).unwrap();
   160→                row.insert(col.name.clone(), Value::Uuid(uuid));
   161→                table.next_seq += 1;
   162→                continue;
   163→            }
   164→            // @default 값 적용
   165→            for ann in &col.annotations {
   166→                if let Annotation::Default(v) = ann {
   167→                    let val = parse_value(v, &col.col_type);
   168→                    row.insert(col.name.clone(), val);
   169→                }
   170→            }
   171→        }
   172→
   173→        let table = self.tables.get_mut(table_name).unwrap();
   174→
   175→        // 2. NOT NULL 검증
   176→        for col in &columns {
   177→            let required = col.annotations.iter()
   178→                .any(|a| matches!(a, Annotation::Required | Annotation::Primary));
   179→            if required && !row.contains_key(&col.name) {
   180→                return Err(DbError::ConstraintViolation(
   181→                    format!("필드 '{}' 값 없음 (NOT NULL)", col.name)
   182→                ));
   183→            }
   184→        }
   185→
   186→        // 3. PK 중복 검증
   187→        if let Some(ref pk) = primary_key {
