   279→// ============================================================
   280→// 표현식 평가 (행 + 환경 컨텍스트)
   281→// ============================================================
   282→
   283→pub fn eval(expr: &Expr, row: &Row, env: &Env) -> Value {
   284→    match expr {
   285→        Expr::Int(n) => Value::Int(*n),
   286→        Expr::Float(f) => Value::Float(*f),
   287→        Expr::Str(s) => Value::Str(s.clone()),
   288→        Expr::Ident(name) => {
   289→            // 행 필드 우선, 없으면 env
   290→            row.get(name)
   291→                .or_else(|| env.get(name))
   292→                .cloned()
   293→                .unwrap_or(Value::Null)
   294→        }
   295→        Expr::BinOp { op, left, right } => {
   296→            let l = eval(left, row, env);
   297→            let r = eval(right, row, env);
   298→            eval_binop(op, l, r)
   299→        }
   300→        Expr::Field { object, field } => {
   301→            if let Expr::Ident(obj) = object.as_ref() {
   302→                let key = format!("{}.{}", obj, field);
   303→                env.get(&key).or_else(|| row.get(&key)).cloned().unwrap_or(Value::Null)
   304→            } else {
   305→                Value::Null
   306→            }
   307→        }
   308→        _ => Value::Null,
   309→    }
   310→}
   311→
   312→fn eval_binop(op: &str, l: Value, r: Value) -> Value {
   313→    match op {
   314→        "+" => add_values(l, r),
   315→        "-" => sub_values(l, r),
   316→        "*" => mul_values(l, r),
   317→        "/" => div_values(l, r),
   318→        "==" => Value::Bool(values_eq(&l, &r)),
   319→        "!=" => Value::Bool(!values_eq(&l, &r)),
   320→        "<"  => Value::Bool(values_lt(&l, &r)),
   321→        "<=" => Value::Bool(values_lt(&l, &r) || values_eq(&l, &r)),
   322→        ">"  => Value::Bool(!values_lt(&l, &r) && !values_eq(&l, &r)),
   323→        ">=" => Value::Bool(!values_lt(&l, &r)),
   324→        _    => Value::Null,
   325→    }
   326→}
   327→
   328→fn add_values(l: Value, r: Value) -> Value {
   329→    match (l, r) {
   330→        (Value::Int(a), Value::Int(b)) => Value::Int(a + b),
   331→        (Value::Float(a), Value::Float(b)) => Value::Float(a + b),
   332→        (Value::Int(a), Value::Float(b)) => Value::Float(a as f64 + b),
   333→        (Value::Float(a), Value::Int(b)) => Value::Float(a + b as f64),
   334→        _ => Value::Null,
   335→    }
   336→}
   337→
   338→fn sub_values(l: Value, r: Value) -> Value {
   339→    match (l, r) {
   340→        (Value::Int(a), Value::Int(b)) => Value::Int(a - b),
   341→        (Value::Float(a), Value::Float(b)) => Value::Float(a - b),
   342→        (Value::Int(a), Value::Float(b)) => Value::Float(a as f64 - b),
   343→        (Value::Float(a), Value::Int(b)) => Value::Float(a - b as f64),
   344→        _ => Value::Null,
   345→    }
   346→}
   347→
   348→fn mul_values(l: Value, r: Value) -> Value {
   349→    match (l, r) {
   350→        (Value::Int(a), Value::Int(b)) => Value::Int(a * b),
   351→        (Value::Float(a), Value::Float(b)) => Value::Float(a * b),
   352→        (Value::Int(a), Value::Float(b)) => Value::Float(a as f64 * b),
   353→        (Value::Float(a), Value::Int(b)) => Value::Float(a * b as f64),
   354→        _ => Value::Null,
   355→    }
   356→}
   357→
   358→fn div_values(l: Value, r: Value) -> Value {
   359→    match (l, r) {
   360→        (Value::Int(a), Value::Int(b)) if b != 0 => Value::Int(a / b),
   361→        (Value::Float(a), Value::Float(b)) if b != 0.0 => Value::Float(a / b),
   362→        (Value::Int(a), Value::Float(b)) => Value::Float(a as f64 / b),
   363→        (Value::Float(a), Value::Int(b)) if b != 0 => Value::Float(a / b as f64),
   364→        _ => Value::Null,
   365→    }
   366→}
   367→
   368→fn values_eq(a: &Value, b: &Value) -> bool {
   369→    match (a, b) {
   370→        (Value::Int(x), Value::Int(y)) => x == y,
   371→        (Value::Float(x), Value::Float(y)) => (x - y).abs() < f64::EPSILON,
   372→        (Value::Str(x), Value::Str(y)) => x == y,
   373→        (Value::Bool(x), Value::Bool(y)) => x == y,
   374→        (Value::Uuid(x), Value::Uuid(y)) => x == y,
   375→        (Value::Null, Value::Null) => true,
   376→        _ => false,
   377→    }
   378→}
   379→
   380→fn values_lt(a: &Value, b: &Value) -> bool {
   381→    match (a, b) {
   382→        (Value::Int(x), Value::Int(y)) => x < y,
   383→        (Value::Float(x), Value::Float(y)) => x < y,
   384→        (Value::Int(x), Value::Float(y)) => (*x as f64) < *y,
   385→        (Value::Float(x), Value::Int(y)) => *x < (*y as f64),
   386→        _ => false,
   387→    }
   388→}
