#[derive(Debug, Clone)]
pub struct Route {
    pub intent: String,
    pub action: String,
    pub params: Vec<(String, FlType)>,
    pub method: &'static str,
    pub path: String,
}

// ============================================================
// Router - IntentGraph → 라우트 테이블
