// ─── validate ─────────────────────────────────────────────

fn cmd_validate(path: &str) {
    let src = read_file(path);
    match parse_and_validate(&src) {
        Err(e) => {
            eprintln!("파싱 오류: {}", e);
            process::exit(1);
        }
        Ok((graph, errors)) => {
            let deficiencies = DeficiencyDetector::analyze(&graph);
            let err_count  = errors.len();
            let def_errors = deficiencies.iter().filter(|d| matches!(d.severity, world_engine::deficiency::Severity::Error)).count();
            let warnings   = deficiencies.iter().filter(|d| matches!(d.severity, world_engine::deficiency::Severity::Warning)).count();

            if errors.is_empty() && def_errors == 0 {
                println!("OK '{}'", path);
                println!("  intents: {}", graph.intents.len());
                if warnings > 0 {
                    println!("  경고: {}", warnings);
                    for d in deficiencies.iter().filter(|d| matches!(d.severity, world_engine::deficiency::Severity::Warning)) {
                        println!("    [WARN] {} - {}: {}", d.intent, d.kind.label(), d.message);
                    }
                }
            } else {
                if err_count > 0 {
                    println!("검증 오류 ({}):", err_count);
                    for e in &errors {
                        println!("  [ERROR] {}", e);
                    }
                }
                if def_errors > 0 {
                    println!("구조 오류 ({}):", def_errors);
                    for d in deficiencies.iter().filter(|d| matches!(d.severity, world_engine::deficiency::Severity::Error)) {
                        println!("  [ERROR] {} - {}: {}", d.intent, d.kind.label(), d.message);
                    }
                }
                process::exit(1);
            }
        }
    }
}

// ─── inspect ──────────────────────────────────────────────

fn cmd_inspect(path: &str, aspect: InspectAspect) {
    let src = read_file(path);
    let (graph, _) = parse_and_validate(&src).unwrap_or_else(|e| {
        eprintln!("파싱 오류: {}", e);
        process::exit(1);
    });

    match aspect {
        InspectAspect::All => {
            println!("=== Intent Graph: {} ===", path);
            println!();
            print_routes(&graph);
            println!();
            print_lifecycle(&graph);
            println!();
            print_deficiencies(&graph);
            println!();
            print_views(&graph);
        }
        InspectAspect::Routes       => print_routes(&graph),
        InspectAspect::Lifecycle    => print_lifecycle(&graph),
        InspectAspect::Deficiencies => print_deficiencies(&graph),
        InspectAspect::Views        => print_views(&graph),
    }
}

fn print_routes(graph: &world_engine::IntentGraph) {
    let router = Router::from_graph(graph.clone());
    println!("Routes ({}):", router.routes.len());
    for r in &router.routes {
        println!("  {:4} {}", r.method, r.path);
    }
    println!("  GET  /emit/{{target}}");
    println!("  POST /mutate");
    println!("  GET  /mutations");
    println!("  GET  /lifecycle");
    println!("  GET  /deficiencies");
    println!("  GET  /health");
}

fn print_lifecycle(graph: &world_engine::IntentGraph) {
    let lc = LifecycleManager::from_graph(graph);
    println!("Lifecycle:");
    let status = lc.status_json();
    for intent in &graph.intents {
        let entry = &status[&intent.name];
        println!("  {} — {}", intent.name,
            entry["lifecycle"].as_str().unwrap_or("unknown"));
    }
}

fn print_deficiencies(graph: &world_engine::IntentGraph) {
    let report = DeficiencyDetector::report_json(graph);
    let total   = report["summary"]["total"].as_u64().unwrap_or(0);
    let errors  = report["summary"]["errors"].as_u64().unwrap_or(0);
    let warnings= report["summary"]["warnings"].as_u64().unwrap_or(0);
    println!("Deficiencies: total={} errors={} warnings={}", total, errors, warnings);
    if let Some(by_intent) = report["by_intent"].as_object() {
        for (intent, items) in by_intent {
            if let Some(arr) = items.as_array() {
                for item in arr {
                    println!("  [{}] {} - {}",
                        item["severity"].as_str().unwrap_or("?"),
                        intent,
                        item["message"].as_str().unwrap_or(""));
                }
            }
        }
    }
}

fn print_views(graph: &world_engine::IntentGraph) {
    println!("Views:");
    for intent in &graph.intents {
        for view in &intent.views {
            let vtype = match &view.view_type {
                world_engine::ast::ViewType::Grid       => "Grid",
                world_engine::ast::ViewType::List       => "List",
                world_engine::ast::ViewType::Form       => "Form",
                world_engine::ast::ViewType::Custom(s)  => s.as_str(),
            };
            println!("  {}/{} [{}] source={}", intent.name, view.name, vtype, view.source);
        }
    }
}

// ─── 공통 유틸 ───────────────────────────────────────────

