fn cmd_run(path: &str, port: u16, hot_reload: bool, persist_path: Option<&str>) {
    let src = read_file(path);

    let graph = parse(&src).unwrap_or_else(|e| {
        eprintln!("파싱 오류: {}", e);
        process::exit(1);
    });

    let result = Synthesizer::synthesize(&graph);
    println!("{}", result.summary());

    let router = Router::from_graph(graph.clone());
    println!("라우트:");
    for r in &router.routes {
        println!("  {} {}", r.method, r.path);
    }
    println!();

    let mut db = result.db;

    // persist: 스냅샷 복원
    let pm_arc = persist_path.map(|p| {
        let cfg = PersistConfig::new(p).with_interval(30);
        let pm = Arc::new(PersistManager::new(cfg));
        pm.restore_if_exists(&mut db);
        pm
    });

    let mut server = Server::new(router, db, port);

    if hot_reload {
        server = server.with_hot_reload(path);
    }
    if let Some(pm) = pm_arc {
        server = server.with_persist(pm);
    }

    server.start().unwrap_or_else(|e| {
        eprintln!("서버 오류: {}", e);
        process::exit(1);
    });
}

