use world_engine::{
    parse,
    synthesizer::{
        Synthesizer,
        kimdb::{KimDB, Value},
        persist::{PersistConfig, PersistManager, save_snapshot, load_snapshot},
    },
};
use std::collections::HashMap;
use std::sync::Arc;

fn tmp_path(name: &str) -> String {
    format!("/tmp/world_engine_test_{}.json", name)
}

fn cleanup(path: &str) {
    let _ = std::fs::remove_file(path);
    let _ = std::fs::remove_file(format!("{}.tmp", path));
}

const BASE_FL: &str = r#"
intent ShopWorld {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Product {
        id: uuid @primary,
        name: string @required,
        qty: i64 @default(0),
    }
    action restock(product_id: uuid, amount: i64) {
        update Product set qty = qty + amount where id == product_id;
        return amount;
    }
}
"#;

fn make_db() -> KimDB {
    let graph = parse(BASE_FL).unwrap();
    let result = Synthesizer::synthesize(&graph);
    result.db
}

fn make_db_with_rows() -> KimDB {
    let mut db = make_db();
    let mut row1 = HashMap::new();
    row1.insert("name".into(), Value::Str("Apple".into()));
    row1.insert("qty".into(), Value::Int(10));
    db.insert("Product", row1).unwrap();

    let mut row2 = HashMap::new();
    row2.insert("name".into(), Value::Str("Banana".into()));
    row2.insert("qty".into(), Value::Int(5));
    db.insert("Product", row2).unwrap();
    db
}

// ─── to_snapshot / apply_snapshot ────────────────────────

#[test]
fn test_snapshot_has_version() {
    let db = make_db();
    let snap = db.to_snapshot();
    assert_eq!(snap["version"].as_u64().unwrap(), 1);
}

#[test]
fn test_snapshot_has_tables() {
    let db = make_db();
    let snap = db.to_snapshot();
    assert!(snap["tables"]["Product"].is_object());
}

#[test]
fn test_snapshot_has_timestamp() {
    let db = make_db();
    let snap = db.to_snapshot();
    assert!(snap["saved_at"].as_u64().unwrap() > 0);
}

#[test]
fn test_snapshot_rows_serialized() {
    let db = make_db_with_rows();
    let snap = db.to_snapshot();
    let rows = snap["tables"]["Product"]["rows"].as_array().unwrap();
    assert_eq!(rows.len(), 2);
}

#[test]
fn test_apply_snapshot_restores_rows() {
    let db_orig = make_db_with_rows();
    let snap = db_orig.to_snapshot();

    let mut db2 = make_db(); // 빈 DB
    let restored = db2.apply_snapshot(&snap).unwrap();
    assert_eq!(restored, 2);
    assert_eq!(db2.row_count("Product"), 2);
}

#[test]
fn test_apply_snapshot_value_types() {
    let db_orig = make_db_with_rows();
    let snap = db_orig.to_snapshot();

    let mut db2 = make_db();
    db2.apply_snapshot(&snap).unwrap();

    let rows = db2.select_all("Product").unwrap();
    let names: Vec<&str> = rows.iter()
        .filter_map(|r| if let Value::Str(s) = r.get("name")? { Some(s.as_str()) } else { None })
        .collect();
    assert!(names.contains(&"Apple"));
    assert!(names.contains(&"Banana"));
}

#[test]
fn test_apply_snapshot_qty_values() {
    let db_orig = make_db_with_rows();
    let snap = db_orig.to_snapshot();

    let mut db2 = make_db();
    db2.apply_snapshot(&snap).unwrap();

    let rows = db2.select_all("Product").unwrap();
    let qtys: Vec<i64> = rows.iter()
        .filter_map(|r| if let Value::Int(n) = r.get("qty")? { Some(*n) } else { None })
        .collect();
    assert!(qtys.contains(&10));
    assert!(qtys.contains(&5));
}

#[test]
fn test_apply_snapshot_uuid_preserved() {
    let db_orig = make_db_with_rows();
    let orig_rows = db_orig.select_all("Product").unwrap();
    let orig_ids: Vec<String> = orig_rows.iter()
        .filter_map(|r| if let Value::Uuid(u) = r.get("id")? { Some(u.clone()) } else { None })
        .collect();

    let snap = db_orig.to_snapshot();
    let mut db2 = make_db();
    db2.apply_snapshot(&snap).unwrap();

    let rows2 = db2.select_all("Product").unwrap();
    let ids2: Vec<String> = rows2.iter()
        .filter_map(|r| if let Value::Uuid(u) = r.get("id")? { Some(u.clone()) } else { None })
        .collect();

    for id in &orig_ids {
        assert!(ids2.contains(id), "UUID {} 복원 안 됨", id);
    }
}

// ─── PersistManager 파일 저장/로드 ───────────────────────

#[test]
fn test_save_creates_file() {
    let path = tmp_path("save_creates");
    cleanup(&path);

