    let pm = PersistManager::new(PersistConfig::new(&path));
    pm.save(&db).unwrap();

    assert!(std::path::Path::new(&path).exists());
    cleanup(&path);
}

#[test]
fn test_save_increment_count() {
    let path = tmp_path("save_count");
    cleanup(&path);

    let db = make_db_with_rows();
    let pm = PersistManager::new(PersistConfig::new(&path));
    pm.save(&db).unwrap();
    pm.save(&db).unwrap();

    assert_eq!(pm.save_count(), 2);
    cleanup(&path);
}

#[test]
fn test_load_returns_json() {
    let path = tmp_path("load_json");
    cleanup(&path);

    let db = make_db_with_rows();
    let pm = PersistManager::new(PersistConfig::new(&path));
    pm.save(&db).unwrap();

    let loaded = pm.load().unwrap();
    assert_eq!(loaded["version"].as_u64().unwrap(), 1);
    cleanup(&path);
}

#[test]
fn test_load_nonexistent_fails() {
    let pm = PersistManager::new(PersistConfig::new("/tmp/nonexistent_world_engine.json"));
