    let graph = parse(BASE_FL).unwrap();
    let result = Synthesizer::synthesize(&graph);
    let pm = Arc::new(PersistManager::new(PersistConfig::new(&path)));
    let mut router = Router::from_graph(graph).with_persist(Arc::clone(&pm));
    let (status, json) = router.handle(&mut { result.db }, "POST", "/snapshot", "");
    assert_eq!(status, 200);
    assert!(json["ok"].as_bool().unwrap());
    assert!(std::path::Path::new(&path).exists());
    cleanup(&path);
}

