use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::time::SystemTime;
use crate::synthesizer::kimdb::{KimDB, Value, Row};
use crate::binder::codec::value_to_json;

// ============================================================
// Snapshot - KimDB 직렬화 포맷
// ============================================================

// Value → serde_json::Value (타입 태그 포함)
fn value_to_tagged(val: &Value) -> serde_json::Value {
    match val {
        Value::Int(n)   => serde_json::json!({ "t": "i", "v": n }),
        Value::Float(f) => serde_json::json!({ "t": "f", "v": f }),
        Value::Str(s)   => serde_json::json!({ "t": "s", "v": s }),
        Value::Bool(b)  => serde_json::json!({ "t": "b", "v": b }),
        Value::Uuid(u)  => serde_json::json!({ "t": "u", "v": u }),
        Value::Null     => serde_json::json!({ "t": "n" }),
    }
}

fn tagged_to_value(json: &serde_json::Value) -> Value {
    let t = json["t"].as_str().unwrap_or("n");
    match t {
        "i" => json["v"].as_i64().map(Value::Int).unwrap_or(Value::Null),
        "f" => json["v"].as_f64().map(Value::Float).unwrap_or(Value::Null),
        "s" => json["v"].as_str().map(|s| Value::Str(s.into())).unwrap_or(Value::Null),
        "b" => json["v"].as_bool().map(Value::Bool).unwrap_or(Value::Null),
        "u" => json["v"].as_str().map(|s| Value::Uuid(s.into())).unwrap_or(Value::Null),
        _   => Value::Null,
    }
}

pub fn row_to_snapshot(row: &Row) -> serde_json::Value {
    let mut keys: Vec<&String> = row.keys().collect();
    keys.sort();
    let map: serde_json::Map<String, serde_json::Value> = keys.iter()
        .map(|k| ((*k).clone(), value_to_tagged(&row[*k])))
        .collect();
    serde_json::Value::Object(map)
}

pub fn snapshot_to_row(json: &serde_json::Value) -> Row {
    let mut row = HashMap::new();
    if let Some(obj) = json.as_object() {
        for (k, v) in obj {
            row.insert(k.clone(), tagged_to_value(v));
        }
    }
    row
}

// ============================================================
// KimDB 스냅샷 확장 메서드
// ============================================================

impl KimDB {
    /// 현재 DB 상태를 JSON 스냅샷으로 직렬화
    pub fn to_snapshot(&self) -> serde_json::Value {
        let tables: serde_json::Value = serde_json::Value::Object(
            self.table_names().iter().map(|name| {
                let rows: Vec<serde_json::Value> = self.select_all(name)
                    .unwrap_or_default()
                    .iter()
                    .map(|r| row_to_snapshot(r))
                    .collect();
                (name.clone(), serde_json::json!({
                    "rows": rows,
                    "count": rows.len(),
                }))
            }).collect()
        );

        let ts = SystemTime::now()
            .duration_since(SystemTime::UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs();

        serde_json::json!({
            "version": 1,
            "saved_at": ts,
            "tables": tables,
        })
    }

    /// JSON 스냅샷으로부터 rows 복원
    /// (provision()으로 스키마가 이미 세팅된 상태에서 호출)
    pub fn apply_snapshot(&mut self, snapshot: &serde_json::Value) -> Result<usize, String> {
        let tables = snapshot["tables"].as_object()
            .ok_or("스냅샷에 'tables' 필드 없음")?;

        let mut total = 0usize;
        for (table_name, table_data) in tables {
            let rows = match table_data["rows"].as_array() {
                Some(r) => r,
                None    => continue,
            };
            for row_json in rows {
                let row = snapshot_to_row(row_json);
                match self.insert_raw(table_name, row) {
                    Ok(_) => total += 1,
                    Err(e) => eprintln!("[persist] insert_raw 실패 '{}': {}", table_name, e),
                }
            }
        }
        Ok(total)
    }

    /// row를 검증 없이 직접 삽입 (스냅샷 복원 전용)
    pub fn insert_raw(&mut self, table_name: &str, row: Row) -> Result<(), String> {
        let table = self.tables.get_mut(table_name)
            .ok_or_else(|| format!("테이블 없음: '{}'", table_name))?;
        table.rows.push(row);
        Ok(())
    }
}

// ============================================================
// PersistManager - 파일 저장/로드 관리
// ============================================================

#[derive(Debug, Clone)]
pub struct PersistConfig {
    pub path: PathBuf,
    pub auto_save_secs: u64, // 0 = 자동 저장 비활성
}

impl PersistConfig {
    pub fn new(path: &str) -> Self {
        PersistConfig {
            path: PathBuf::from(path),
            auto_save_secs: 30,
        }
    }

    pub fn with_interval(mut self, secs: u64) -> Self {
        self.auto_save_secs = secs;
        self
    }
}

pub struct PersistManager {
    pub config: PersistConfig,
    pub last_save: Mutex<Option<SystemTime>>,
    pub save_count: Mutex<u64>,
    pub last_error: Mutex<Option<String>>,
}

impl PersistManager {
    pub fn new(config: PersistConfig) -> Self {
        PersistManager {
            config,
            last_save: Mutex::new(None),
            save_count: Mutex::new(0),
            last_error: Mutex::new(None),
        }
    }

    /// DB 상태를 파일에 저장
    pub fn save(&self, db: &KimDB) -> Result<(), String> {
        let snapshot = db.to_snapshot();
        let json = serde_json::to_string_pretty(&snapshot)
            .map_err(|e| format!("직렬화 실패: {}", e))?;

        // 원자적 저장: 임시 파일 → rename
        let tmp = self.config.path.with_extension("tmp");
        fs::write(&tmp, &json)
            .map_err(|e| format!("파일 쓰기 실패 '{}': {}", tmp.display(), e))?;
        fs::rename(&tmp, &self.config.path)
            .map_err(|e| format!("파일 이동 실패: {}", e))?;

        *self.last_save.lock().unwrap() = Some(SystemTime::now());
        *self.save_count.lock().unwrap() += 1;
        Ok(())
    }

    /// 파일에서 스냅샷 로드
    pub fn load(&self) -> Result<serde_json::Value, String> {
        if !self.config.path.exists() {
            return Err(format!("스냅샷 파일 없음: '{}'", self.config.path.display()));
        }
        let json = fs::read_to_string(&self.config.path)
            .map_err(|e| format!("파일 읽기 실패: {}", e))?;
        serde_json::from_str(&json)
            .map_err(|e| format!("JSON 파싱 실패: {}", e))
    }

    /// 파일이 있으면 DB에 복원
    pub fn restore_if_exists(&self, db: &mut KimDB) -> Option<usize> {
        match self.load() {
            Ok(snapshot) => {
                match db.apply_snapshot(&snapshot) {
                    Ok(n) => {
                        println!("[persist] 스냅샷 복원: {} rows ({})",
                            n, self.config.path.display());
                        Some(n)
                    }
                    Err(e) => {
                        *self.last_error.lock().unwrap() = Some(e.clone());
                        eprintln!("[persist] 복원 실패: {}", e);
                        None
                    }
                }
            }
            Err(_) => None, // 파일 없음은 정상
        }
    }

    pub fn file_exists(&self) -> bool {
        self.config.path.exists()
    }

    pub fn file_size_bytes(&self) -> u64 {
        fs::metadata(&self.config.path)
            .map(|m| m.len())
            .unwrap_or(0)
    }

    pub fn save_count(&self) -> u64 {
        *self.save_count.lock().unwrap()
    }

    pub fn last_save_unix(&self) -> Option<u64> {
        self.last_save.lock().unwrap().and_then(|t| {
            t.duration_since(SystemTime::UNIX_EPOCH).ok().map(|d| d.as_secs())
        })
    }

    pub fn status_json(&self) -> serde_json::Value {
        serde_json::json!({
            "enabled": true,
            "path": self.config.path.to_str().unwrap_or("?"),
            "auto_save_secs": self.config.auto_save_secs,
            "file_exists": self.file_exists(),
            "file_size_bytes": self.file_size_bytes(),
            "save_count": self.save_count(),
            "last_save_unix": self.last_save_unix(),
            "last_error": *self.last_error.lock().unwrap(),
        })
    }
}

// ============================================================
// Server 자동 저장 스레드 헬퍼
// ============================================================

/// 백그라운드 자동 저장 스레드를 시작
/// db_lock: Arc<Mutex<KimDB>>, pm: Arc<PersistManager>, interval_secs
pub fn start_auto_save(
    db_lock: Arc<Mutex<KimDB>>,
    pm: Arc<PersistManager>,
) {
    if pm.config.auto_save_secs == 0 { return; }
    let interval = pm.config.auto_save_secs;
    std::thread::spawn(move || {
        loop {
            std::thread::sleep(std::time::Duration::from_secs(interval));
            if let Ok(db) = db_lock.lock() {
                match pm.save(&db) {
                    Ok(()) => {}
                    Err(e) => {
                        *pm.last_error.lock().unwrap() = Some(e.clone());
                        eprintln!("[persist] 자동 저장 실패: {}", e);
                    }
                }
            }
        }
    });
}

// ============================================================
// 편의 함수
// ============================================================

/// 경로에서 직접 스냅샷 저장
pub fn save_snapshot(db: &KimDB, path: &str) -> Result<(), String> {
    let pm = PersistManager::new(PersistConfig::new(path));
    pm.save(db)
}

/// 경로에서 직접 스냅샷 로드 후 복원
pub fn load_snapshot(db: &mut KimDB, path: &str) -> Result<usize, String> {
    let pm = PersistManager::new(PersistConfig::new(path));
    pm.load().and_then(|snap| db.apply_snapshot(&snap))
}

use std::io::{BufRead, BufReader, Write};
use std::net::{TcpListener, TcpStream};
use std::sync::{Arc, Mutex, RwLock};
use crate::synthesizer::kimdb::KimDB;
use crate::hotreload::HotReloader;
use crate::synthesizer::persist::{PersistManager, start_auto_save};
use super::router::Router;

// ============================================================
// 최소 HTTP 서버 (std only) + Hot-Reload 지원
// ============================================================

pub struct Server {
    pub port: u16,
    router: Arc<RwLock<Router>>,
    db: Arc<Mutex<KimDB>>,
    reloader: Option<Arc<HotReloader>>,
}

impl Server {
    pub fn new(router: Router, db: KimDB, port: u16) -> Self {
        Server {
            port,
            router: Arc::new(RwLock::new(router)),
            db: Arc::new(Mutex::new(db)),
            reloader: None,
        }
    }

    pub fn with_persist(mut self, pm: Arc<PersistManager>) -> Self {
        // router에도 주입
        if let Ok(mut r) = self.router.write() {
            r.persist = Some(Arc::clone(&pm));
        }
        // 자동 저장 스레드 시작
        start_auto_save(Arc::clone(&self.db), Arc::clone(&pm));
        println!("[persist] 스냅샷 영속화 ON: {} ({}초마다 자동 저장)",
            pm.config.path.display(), pm.config.auto_save_secs);
        self
    }

    pub fn with_hot_reload(mut self, path: &str) -> Self {
        let reloader = Arc::new(HotReloader::new(path));
        // router에도 reloader 주입
        if let Ok(mut r) = self.router.write() {
            r.reloader = Some(Arc::clone(&reloader));
        }
        self.reloader = Some(reloader);
        self
    }

    pub fn start(&self) -> std::io::Result<()> {
        let listener = TcpListener::bind(format!("0.0.0.0:{}", self.port))?;
        println!("World Engine 서버 시작: http://0.0.0.0:{}", self.port);
        println!("라우트 목록:   http://0.0.0.0:{}/routes", self.port);
        println!("Lifecycle:     http://0.0.0.0:{}/lifecycle", self.port);
        println!("Deficiencies:  http://0.0.0.0:{}/deficiencies", self.port);
        println!("Reload status: http://0.0.0.0:{}/reload/status", self.port);

        // Lifecycle watcher
        {
            let db = Arc::clone(&self.db);
            let lifecycle = {
                let r = self.router.read().unwrap();
                Arc::clone(&r.lifecycle)
            };
            std::thread::spawn(move || {
                loop {
                    std::thread::sleep(std::time::Duration::from_secs(1));
                    if let (Ok(lc), Ok(mut db)) = (lifecycle.lock(), db.lock()) {
                        for entry in &lc.entries {
                            if entry.is_expired() {
                                for table in &entry.table_names {
                                    db.clear_table(table);
                                }
                            }
                        }
                    }
                }
            });
        }

        // Hot-reload watcher
        if let Some(reloader) = &self.reloader {
            let reloader = Arc::clone(reloader);
            let router_lock = Arc::clone(&self.router);
            let db_lock = Arc::clone(&self.db);
            println!("Hot-Reload ON: {}", reloader.path_str());

            std::thread::spawn(move || {
                loop {
                    std::thread::sleep(std::time::Duration::from_secs(1));
                    if let Some(result) = reloader.check_and_reload() {
                        match result {
                            Ok(new_graph) => {
                                // 새 스키마 provision (기존 데이터 유지)
                                if let Ok(mut db) = db_lock.lock() {
                                    let existing = db.table_names();
                                    for intent in &new_graph.intents {
                                        for schema in &intent.schemas {
                                            if !existing.contains(&schema.name) {
                                                db.provision(schema);
                                            }
                                        }
                                    }
                                }
                                // Router 교체
                                let new_router = Router::from_graph(new_graph)
                                    .with_reloader(Arc::clone(&reloader));
                                if let Ok(mut r) = router_lock.write() {
                                    *r = new_router;
                                    println!("[hot-reload] 라우트 갱신 완료 (reload #{})", reloader.reload_count());
                                }
                            }
                            Err(e) => {
                                eprintln!("[hot-reload] 오류: {}", e);
                            }
                        }
                    }
                }
            });
        }

        for stream in listener.incoming() {
            match stream {
                Ok(stream) => {
                    let router = Arc::clone(&self.router);
                    let db = Arc::clone(&self.db);
                    std::thread::spawn(move || {
                        handle_connection(stream, router, db);
                    });
                }
                Err(e) => eprintln!("연결 오류: {}", e),
            }
        }
        Ok(())
    }
}

fn handle_connection(
    mut stream: TcpStream,
    router: Arc<RwLock<Router>>,
    db: Arc<Mutex<KimDB>>,
) {
    let request = match parse_request(&stream) {
        Some(r) => r,
        None => {
            let _ = write_response(&mut stream, 400, r#"{"error":"bad request"}"#);
            return;
        }
    };

    let mut db = db.lock().unwrap();
    // POST /mutate는 graph 변경 → write lock, 나머지는 read lock
    let (status, json) = if request.method == "POST" && request.path == "/mutate" {
        let mut router = router.write().unwrap();
        router.handle(&mut db, &request.method, &request.path, &request.body)
    } else {
        let mut router = router.write().unwrap(); // handle이 &mut self이므로 write
        router.handle(&mut db, &request.method, &request.path, &request.body)
    };

    // _html 마커: HTML 응답
    if let Some(html) = json.get("_html").and_then(|v| v.as_str()) {
        let _ = write_html_response(&mut stream, status, html);
    } else {
        let body = json.to_string();
        let _ = write_response(&mut stream, status, &body);
    }
}

// ─── HTTP 파싱 ──────────────────────────────────────────────

struct RawRequest {
    method: String,
    path: String,
    body: String,
}

fn parse_request(stream: &TcpStream) -> Option<RawRequest> {
    let mut reader = BufReader::new(stream);
    let mut lines = Vec::new();
    let mut content_length = 0usize;

    loop {
        let mut line = String::new();
        reader.read_line(&mut line).ok()?;
        let line = line.trim_end_matches("\r\n").trim_end_matches('\n').to_string();
        if line.is_empty() { break; }

        let lower = line.to_lowercase();
        if lower.starts_with("content-length:") {
            content_length = lower.split(':').nth(1)
                .and_then(|v| v.trim().parse().ok())
                .unwrap_or(0);
        }
        lines.push(line);
    }

    let first = lines.first()?;
    let parts: Vec<&str> = first.splitn(3, ' ').collect();
    if parts.len() < 2 { return None; }

    let method = parts[0].to_string();
    let path = parts[1].to_string();

    let mut body = String::new();
    if content_length > 0 {
        let mut buf = vec![0u8; content_length];
        use std::io::Read;
        reader.read_exact(&mut buf).ok()?;
        body = String::from_utf8_lossy(&buf).to_string();
    }

    Some(RawRequest { method, path, body })
}

fn write_html_response(stream: &mut TcpStream, status: u16, html: &str) -> std::io::Result<()> {
    let response = format!(
        "HTTP/1.1 {} OK\r\nContent-Type: text/html; charset=utf-8\r\nContent-Length: {}\r\nAccess-Control-Allow-Origin: *\r\n\r\n{}",
        status, html.len(), html
    );
    stream.write_all(response.as_bytes())?;
    stream.flush()
}

fn write_response(stream: &mut TcpStream, status: u16, body: &str) -> std::io::Result<()> {
    let status_text = match status {
        200 => "OK",
        400 => "Bad Request",
        404 => "Not Found",
        500 => "Internal Server Error",
        _ => "Unknown",
    };
    let response = format!(
        "HTTP/1.1 {} {}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nAccess-Control-Allow-Origin: *\r\n\r\n{}",
        status, status_text, body.len(), body
    );
    stream.write_all(response.as_bytes())?;
    stream.flush()
}

