use std::collections::HashMap;
use std::time::SystemTime;

// ============================================================
// 권한 레벨
// ============================================================

#[derive(Debug, Clone, PartialEq, PartialOrd)]
pub enum Permission {
    ReadOnly,   // GET 요청만 허용
    ReadWrite,  // GET + POST (mutate/snapshot 포함)
    Admin,      // 전체 허용 + 관리 API
}

impl Permission {
    pub fn from_str(s: &str) -> Self {
        match s.to_lowercase().as_str() {
            "readonly" | "read"  => Permission::ReadOnly,
            "readwrite"| "write" => Permission::ReadWrite,
            "admin"              => Permission::Admin,
            _                    => Permission::ReadOnly,
        }
    }

    pub fn as_str(&self) -> &'static str {
        match self {
            Permission::ReadOnly  => "readonly",
            Permission::ReadWrite => "readwrite",
            Permission::Admin     => "admin",
        }
    }

    pub fn allows_write(&self) -> bool {
        matches!(self, Permission::ReadWrite | Permission::Admin)
    }

    pub fn is_admin(&self) -> bool {
        matches!(self, Permission::Admin)
    }
}

// ============================================================
// API Key
// ============================================================

#[derive(Debug, Clone)]
pub struct ApiKey {
    pub raw: String,         // "we_<32hex>"
    pub label: String,       // 사람이 읽기 쉬운 이름
    pub permission: Permission,
    pub created_at: u64,     // unix secs
    pub use_count: u64,
}

impl ApiKey {
    /// 새 API Key 생성 (we_ + 32자 hex)
    pub fn generate(label: &str, permission: Permission) -> Self {
        let ts = SystemTime::now()
            .duration_since(SystemTime::UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos();
        // 간단한 PRNG (결정론적 - 테스트용으로도 충분)
        let raw = format!("we_{}", generate_hex(ts as u64, label));
        let now = ts as u64 / 1_000_000_000;
        ApiKey { raw, label: label.to_string(), permission, created_at: now, use_count: 0 }
    }

    pub fn to_json(&self) -> serde_json::Value {
        serde_json::json!({
            "label": self.label,
            "raw": self.raw,
            "permission": self.permission.as_str(),
            "created_at": self.created_at,
            "use_count": self.use_count,
        })
    }
}

/// 간단한 hex 생성 (외부 crate 없이)
fn generate_hex(seed: u64, salt: &str) -> String {
    let mut state = seed.wrapping_add(0x9e3779b97f4a7c15);
    for b in salt.bytes() {
        state = state.wrapping_mul(6364136223846793005)
            .wrapping_add(b as u64)
            .wrapping_add(0x14057b7ef767814f);
    }
    // 32자 hex = 4 x 8자리
    let mut out = String::with_capacity(32);
    for i in 0..4u64 {
        let v = state.wrapping_mul(i.wrapping_add(1))
            .wrapping_add(0x9e3779b97f4a7c15)
            .rotate_left(17)
            .wrapping_add(state);
        state = v;
        out.push_str(&format!("{:016x}", v));
    }
    out[..32].to_string()
}

// ============================================================
// ApiKeyStore
// ============================================================

pub struct ApiKeyStore {
    keys: HashMap<String, ApiKey>, // raw → ApiKey
}

impl ApiKeyStore {
    pub fn new() -> Self {
        ApiKeyStore { keys: HashMap::new() }
    }

    pub fn add(&mut self, key: ApiKey) {
        self.keys.insert(key.raw.clone(), key);
    }

    pub fn get(&self, raw: &str) -> Option<&ApiKey> {
        self.keys.get(raw)
    }

    pub fn get_mut(&mut self, raw: &str) -> Option<&mut ApiKey> {
        self.keys.get_mut(raw)
    }

    pub fn remove(&mut self, raw: &str) -> bool {
        self.keys.remove(raw).is_some()
    }

    pub fn count(&self) -> usize {
        self.keys.len()
    }

    pub fn list_json(&self) -> serde_json::Value {
        let mut keys: Vec<_> = self.keys.values().collect();
        keys.sort_by_key(|k| k.created_at);
        serde_json::json!(keys.iter().map(|k| k.to_json()).collect::<Vec<_>>())
    }

    pub fn verify(&mut self, raw: &str) -> Option<Permission> {
        if let Some(key) = self.keys.get_mut(raw) {
            key.use_count += 1;
            Some(key.permission.clone())
        } else {
            None
        }
    }
}

impl Default for ApiKeyStore {
    fn default() -> Self { Self::new() }
}

