use std::collections::HashMap;
use std::sync::Arc;
use world_engine::auth::{
    AuthManager, AuthResult,
    apikey::Permission,
    token::{AuthToken, TokenError},
    middleware::{AuthConfig, AuthMiddleware, parse_headers},
};

fn make_manager() -> AuthManager {
    AuthManager::new(AuthConfig::new("test-secret-key"))
}

fn headers(pairs: &[(&str, &str)]) -> HashMap<String, String> {
    pairs.iter().map(|(k, v)| (k.to_string(), v.to_string())).collect()
}

// ─── Permission ───────────────────────────────────────────

#[test]
fn test_permission_from_str() {
    assert_eq!(Permission::from_str("readonly"), Permission::ReadOnly);
    assert_eq!(Permission::from_str("readwrite"), Permission::ReadWrite);
    assert_eq!(Permission::from_str("admin"), Permission::Admin);
    assert_eq!(Permission::from_str("unknown"), Permission::ReadOnly);
}

#[test]
fn test_permission_ordering() {
    assert!(Permission::ReadOnly  < Permission::ReadWrite);
    assert!(Permission::ReadWrite < Permission::Admin);
}

#[test]
fn test_permission_allows_write() {
    assert!(!Permission::ReadOnly.allows_write());
    assert!(Permission::ReadWrite.allows_write());
    assert!(Permission::Admin.allows_write());
}

#[test]
fn test_permission_is_admin() {
    assert!(!Permission::ReadOnly.is_admin());
    assert!(!Permission::ReadWrite.is_admin());
    assert!(Permission::Admin.is_admin());
}

// ─── API Key 발급 / 검증 ───────────────────────────────────

#[test]
fn test_issue_api_key_has_prefix() {
    let am = make_manager();
    let key = am.issue_api_key("test", Permission::ReadOnly);
    assert!(key.starts_with("we_"), "키 접두사 없음: {}", key);
}

#[test]
fn test_issue_api_key_length() {
    let am = make_manager();
    let key = am.issue_api_key("test", Permission::ReadOnly);
    assert!(key.len() > 10);
}

#[test]
fn test_api_key_authentication_ok() {
    let am = make_manager();
    let key = am.issue_api_key("alice", Permission::ReadWrite);
    let hdrs = headers(&[("x-api-key", &key)]);
    let result = am.authenticate(&hdrs);
    assert_eq!(result, AuthResult::Allowed(Permission::ReadWrite));
}

#[test]
fn test_api_key_invalid_denied() {
    let am = make_manager();
    let hdrs = headers(&[("x-api-key", "we_invalid_key_xxx")]);
    let result = am.authenticate(&hdrs);
    assert!(matches!(result, AuthResult::Denied(_)));
}

#[test]
fn test_api_key_use_count_increments() {
    let am = make_manager();
    let key = am.issue_api_key("bob", Permission::ReadOnly);
    let hdrs = headers(&[("x-api-key", &key)]);
    am.authenticate(&hdrs);
    am.authenticate(&hdrs);
    let store = am.key_store.lock().unwrap();
    assert_eq!(store.get(&key).unwrap().use_count, 2);
}

#[test]
fn test_no_auth_header_denied() {
    let am = make_manager();
    let result = am.authenticate(&headers(&[]));
    assert!(matches!(result, AuthResult::Denied(_)));
}

// ─── Token 발급 / 검증 ────────────────────────────────────

#[test]
fn test_token_encode_decode() {
    let am = make_manager();
    let key = am.issue_api_key("charlie", Permission::ReadWrite);
    let hdrs = headers(&[("x-api-key", &key)]);
    am.authenticate(&hdrs); // key 등록

    let token = am.issue_token("charlie", Permission::ReadWrite);
    let claims = am.verify_token(&token).unwrap();
    assert_eq!(claims.sub, "charlie");
    assert_eq!(claims.permission, Permission::ReadWrite);
}

#[test]
fn test_token_bearer_authentication() {
    let am = make_manager();
    let token = am.issue_token("dave", Permission::ReadOnly);
    let hdrs = headers(&[("authorization", &format!("Bearer {}", token))]);
    let result = am.authenticate(&hdrs);
    assert_eq!(result, AuthResult::Allowed(Permission::ReadOnly));
}

#[test]
fn test_token_invalid_signature() {
    let result = AuthToken::decode("invalid.token.here", "secret");
    assert!(matches!(result, Err(TokenError::InvalidSignature) | Err(TokenError::Malformed)));
}

#[test]
fn test_token_malformed() {
    let result = AuthToken::decode("notavalidtoken", "secret");
    assert!(matches!(result, Err(TokenError::Malformed)));
}

#[test]
fn test_token_revoke() {
    let am = make_manager();
    let token = am.issue_token("eve", Permission::ReadWrite);
    am.revoke_token(&token);
    let result = am.verify_token(&token);
    assert!(matches!(result, Err(TokenError::Revoked)));
}

#[test]
fn test_token_has_jti() {
    let am = make_manager();
    let t1 = am.issue_token("user", Permission::ReadOnly);
    let t2 = am.issue_token("user", Permission::ReadOnly);
    let c1 = am.verify_token(&t1).unwrap();
    let c2 = am.verify_token(&t2).unwrap();
    assert_ne!(c1.jti, c2.jti, "JTI가 같으면 안 됨");
}

