// 구조: base64url(header).base64url(payload).signature
// 서명: FNV-1a64(secret + "." + header + "." + payload)
// ============================================================

#[derive(Debug, Clone, PartialEq)]
pub enum TokenError {
    Malformed,
    InvalidSignature,
    Expired,
    Revoked,
}

impl std::fmt::Display for TokenError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            TokenError::Malformed          => write!(f, "토큰 형식 오류"),
            TokenError::InvalidSignature   => write!(f, "서명 불일치"),
            TokenError::Expired            => write!(f, "토큰 만료"),
            TokenError::Revoked            => write!(f, "폐기된 토큰"),
        }
    }
}

#[derive(Debug, Clone)]
pub struct TokenClaims {
    pub sub: String,        // subject (사용자/키 이름)
    pub permission: Permission,
    pub iat: u64,           // issued at (unix secs)
    pub exp: u64,           // expires at (unix secs)
    pub jti: String,        // JWT ID (고유 식별자)
}

pub struct AuthToken {
    pub claims: TokenClaims,
}

static TOKEN_COUNTER: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(1);

impl AuthToken {
    pub fn new(subject: &str, permission: Permission, ttl_secs: u64, _secret: &str) -> Self {
        let now = SystemTime::now()
            .duration_since(SystemTime::UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos() as u64;
        let counter = TOKEN_COUNTER.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
        let jti = format!("{:x}-{:x}", fnv1a64(subject.as_bytes()) ^ now, counter);
        let now_secs = now / 1_000_000_000;
        AuthToken {
            claims: TokenClaims {
                sub: subject.to_string(),
                permission,
                iat: now_secs,
                exp: now_secs + ttl_secs,
